# -*- coding: utf-8 -*-
"""仁本第一 — 日本語訳。"""

TITLE = '第一篇　仁本（じんぽん）'
HEAD = '''十段。巻頭の一篇であり、七書のうちで最も兵書らしくない一篇でもある。どう戦うかはほとんど説かず、いつ戦ってよいか、戦うあいだ何をしてはならぬかを説く。全書で最も名高い二句がここにある——「戦を以て戦を去るは、戦うといえども可なり」、「国、大なりといえども戦を好めば必ず亡ぶ。天下、安しといえども戦を忘るれば必ず危うし」。篇の後半は出兵の手続きである。まず諸侯に遍く告げ、次に皇天上帝・日月星辰に告げ、后土・四海の神祇・山川冢社に禱り、最後に先王に告げて、そこでようやく冢宰が諸侯に師を徴（あつ）める——この書において戦争はまず礼の一つなのである。続くのは戦場の軍紀で、土功を毀つな、牆屋を燔くな、林木を伐るな、老幼は送り帰して傷つけるな、<i>敵もし傷つかば医薬してこれを帰せ</i>。末段の「発禁九条」は『周礼』大司馬の「九伐の法」とほとんど一字一句同じで、この書が「軍礼」の系統に属することの最も硬い証拠である。『漢書』芸文志は『軍礼司馬法』百五十五篇を兵書略ではなく、六芸略の礼類に入れている。'''

PARA = {
 'p1-1': '古は仁を本とし、義を以てこれを治める、これを正という。正、意を獲ざれば則ち権（けん、臨機の処置）による。権は戦より出で、中人（ちゅうじん、なみの人）より出でない。ゆえに人を殺して人を安んずるならば、殺すも可である。その国を攻めてその民を愛するならば、攻めるも可である。戦を以て戦を去るならば、戦うといえども可である。ゆえに仁は親しまれ、義は悦ばれ、智は恃まれ、勇は身を以て従われ、信は信ぜられる。内に愛を得れば守ることができ、外に威を得れば戦うことができる。（底本は「以義治之、治之為正」「不出於仁也」に作るが、二本はともに訳のごとく作る。「権は仁より出でず」では意をなさず、また「治之」が重出するので、いずれも二本に従って改めた。巻末〈底本と校例〉参照。「勇見身」を四庫本は「勇見方」に作る。「仁本」と題する書が、巻頭の一段でいきなり殺すことと攻めることに道を開く——ただし条件は同じ一文のなかに書き込まれている。）',
 'p1-2': '戦の道は、時に違わず、民の病めるに乗じない。これがわが民を愛するゆえんである。喪に加えず、凶（きょう、凶作）に因らない。これが彼の民を愛するゆえんである。冬と夏には師を興さない。これが双方の民をあわせて愛するゆえんである。ゆえに国、大なりといえども戦を好めば必ず亡び、天下、安しといえども戦を忘るれば必ず危うい。（「歴」は遭遇すること。「夫の其の民」の「夫」は彼、敵国の民をいう。四庫本は「兼ねて其の民を愛す」に作る。末の二句は全書で最も広く伝わった句であり、書全体の骨格でもある——戦を好むのも忘れるのもそれぞれ病であって、この書はどちらの側にも立たない。）',
 'p1-3': '天下すでに平らかなれば、天子は大愷（たいがい、凱旋の楽）を奏し、春には蒐（そう）、秋には獮（せん）の狩をする。諸侯は春に振旅（軍の整列）し、秋に治兵（調練）する。みな戦を忘れないためである。（蒐・獮は春秋二季の狩であり、演武でもある（『周礼』大司馬）。四部叢刊本は「天子大愷」を「天下大愷」に作る。前段が「戦を好めば亡ぶ」と言い、この段が「戦を忘るれば危うし」の処方を出す——演武を年中行事に組み込むこと。）',
 'p1-4': '古は、敗走する者を追うこと百歩を過ぎず、退く者を追うこと三舎（九十里）を過ぎない。これによってその礼を明らかにした。能わざる者を窮めず、傷病者を哀れんだ。これによってその義を明らかにした。列を成すのを待って鼓した。これによってその信を明らかにした。義を争って利を争わなかった。これによってその義を明らかにした。また服する者を舎（ゆる）すことができた。これによってその勇を明らかにした。終わりを知り始めを知った。これによってその智を明らかにした。この六徳を時に応じて教えあわせ、民の紀（きまり）とする道とした。古よりの政である。（「舎」は行軍三十里。「窮不能」は力なき者を窮地に追い込むこと。——ここに全書で最も重い異文がある。「六徳」とは礼・仁・信・義・勇・智のはずだが、底本と影宋鈔本はともに「是を以て其の義を明らかにす」を二度出し、数えると五徳しかない。四庫本は初出を「是を以て其の仁を明らかにす」に作り、六徳が揃い、篇名「仁本」とも応じる。本頁の改字の例は「二本一致して底本通ぜざるもの」であり、ここは一本しか拠るところがないので底本のままとし、事実だけを記す。底本が誤っている可能性が最も高いと私が考え、しかも例に従って改めなかった唯一の箇所である。）',
 'p1-5': '先王の治は、天の道に順（したが）い、地の宜に設け、民の徳あるものを官とした。かくて名を正し物を治め、国を立て職を弁（わか）ち、爵を以て禄を分けた。諸侯は悦び懐（なつ）き、海外も来たり服し、獄は弭（や）み兵は寝（しず）まった。聖徳の治である。（「官民之徳」の「官」は動詞。「弭」は止む、「寝」は息む。四庫本は「聖徳の至りなり」に作る。）',
 'p1-6': 'その次に、賢王が礼楽法度を制し、五刑を作り甲兵を興して不義を討った。四方を巡狩し、諸侯を会し、同じからざるところを考（しら）べた。命を失い常を乱し、徳に背き天の時に逆らい、功ある君を危うくする者があれば、遍く諸侯に告げ、その罪を彰（あき）らかにした。しかるのち皇天上帝・日月星辰に告げ、后土・四海の神祇・山川冢社に禱り、さらに先王に造（いた）り告げた。そのうえで冢宰がはじめて諸侯に師を徴めて言う——「某国、道を為さず、これを征す。某年月日を以て、師は某国に至り、天子の正刑に会せよ」。（「巡狩者方」を四庫本は「巡狩省方」に作る（「省方」は『易』観卦「先王以て方を省み民を観て教を設く」）。文意は四庫本の方が順（すな）おだが底本のままとした。「偏告」を二本はともに「徧告」に作る。「偏」は「徧」の通仮なので底本のまま。「冢社」を四部叢刊本は「冢杜」に作る。全段が出兵の手続きであり、諸侯、天地の神祇、先王、最後に徴兵という順序をとる。この書が他の六書と最も違うところである。）',
 'p1-7': '冢宰と百官は軍中に令を布いて言う——「罪人の地に入らば、神祇を暴（そこな）うなかれ。田猟するなかれ。土功を毀つなかれ。牆屋を燔くなかれ。林木を伐るなかれ。六畜・禾黍・器械を取るなかれ。その老幼を見れば奉じて帰し、傷つけるなかれ。壮者に遇うとも、校（あらが）わざれば敵するなかれ。敵もし傷つかば、医薬してこれを帰せ」。（「土功」は堤防・水路の類。「校」は抵抗すること。四庫本は「奉帰無傷」に作る。現存する中国最古の戦場軍紀であり、七つの「なかれ」が続いたのち、末の二句は敵の傷兵に医薬を与えて送り返せというところまで行く——一八六四年の第一次ジュネーヴ条約に二千年以上先立つ。）',
 'p1-8': 'すでに罪ある者を誅したのち、王と諸侯はその国を修め正し、賢を挙げ明を立て、その職を正し復した。（「正し復す」であって併呑ではない。国を滅ぼすことが目的ではない——前段の軍紀はこの一句に落ちる。）',
 'p1-9': '王者・覇者が諸侯を治めるゆえんのものは六つある。土地を以て諸侯を形（かたど）り（境界を定め）、政令を以て諸侯を平らかにし、礼信を以て諸侯を親しませ、材力を以て諸侯を悦ばせ、謀人を以て諸侯を維（つな）ぎ、兵革を以て諸侯を服させる。患を同じくし利を同じくして諸侯を合わせ、小をして大に事えしめて諸侯を和する。（六つのうち五つまでは兵を用いない。兵革は最後に置かれている。）',
 'p1-10': '諸侯を会して発する禁は九つある。弱きに憑（よ）り寡なきを犯す者は、これを眚（へ）らす。賢を賊（そこな）い民を害する者は、これを伐つ。内に暴（あら）く外を陵ぐ者は、これを壇（しりぞ）ける。野荒れ民散ずる者は、その地を削る。固きに負（たの）みて服さざる者は、これを侵す。その親を賊殺する者は、これを正す。その君を放弑する者は、これを残（ほろ）ぼす。令を犯し政を陵ぐ者は、これを杜（と）ざす。外内乱れ禽獣の行ある者は、これを滅ぼす。（「眚」は減らすこと。「壇」は「墠」で、地を除（はら）って場を作ること、君を廃して立て替える意。「杜」は他国との往来を絶つこと。この九条は『周礼』大司馬の「九伐の法」とほとんど一字一句同じである。『司馬法』はもともと「軍礼」の書であり、これが最も硬い内証である。）',
}
